import type { ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './bento-grid.module.scss'

export interface BentoGridProps {
  children: ReactNode
  className?: string
}

/**
 * Bento mosaic.
 *
 * Column count follows the grid's own width (container queries), not the
 * viewport: one column in a narrow card, two once there is room, and the four
 * column mosaic — with the `colSpan`/`rowSpan` tile sizes — only when the grid
 * is wide enough for them. Rows hug their content until the four column
 * layout, so short tiles do not sit in oversized empty boxes.
 */
export function BentoGrid({ children, className }: BentoGridProps) {
  return (
    <div className={styles.container}>
      <div className={cx(styles.grid, className)}>{children}</div>
    </div>
  )
}

const COL_SPAN = {
  1: '',
  2: styles.colSpan2,
  3: styles.colSpan3,
  4: styles.colSpan4,
} as const

const ROW_SPAN = {
  1: '',
  2: styles.rowSpan2,
  3: styles.rowSpan3,
} as const

export interface BentoItemProps {
  children: ReactNode
  className?: string
  colSpan?: 1 | 2 | 3 | 4
  rowSpan?: 1 | 2 | 3
}

export function BentoItem({
  children,
  className,
  colSpan = 1,
  rowSpan = 1,
}: BentoItemProps) {
  return (
    <div
      className={cx(
        styles.item,
        COL_SPAN[colSpan],
        ROW_SPAN[rowSpan],
        className,
      )}
    >
      {children}
    </div>
  )
}

@use 'styles' as vz;

.container {
  container-type: inline-size;
}

.grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-auto-rows: auto;
  gap: vz.space(3);
}

.item {
  min-width: 0;
  overflow: hidden;
  padding: vz.space(4);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(1);
  transition: box-shadow vz.duration('base') vz.ease('out');

  @include vz.hover {
    box-shadow: vz.elevation(2);
  }
}

@container (min-width: 24rem) {
  .grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@container (min-width: 48rem) {
  .grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    grid-auto-rows: minmax(9rem, auto);
  }

  .col-span-2 {
    grid-column: span 2 / span 2;
  }

  .col-span-3 {
    grid-column: span 3 / span 3;
  }

  .col-span-4 {
    grid-column: span 4 / span 4;
  }

  .row-span-2 {
    grid-row: span 2 / span 2;
  }

  .row-span-3 {
    grid-row: span 3 / span 3;
  }
}
